import os, sys; sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from ficha import *
T="FIBRILACIÓN AURICULAR"; N=7
note=lambda t: f'<div style="font-size:34px;line-height:1.4;color:{G}">{t}</div>'
rows=lambda *x: '<div style="display:flex;flex-direction:column;gap:22px">'+"".join(x)+'</div>'
P=[
page(1,N,T,big("FIBRILACIÓN AURICULAR",104,nowrap=True)+big(f'LO PRIMERO NO ES EL RITMO: ES <span style="color:{R}">CUÁNTAS HORAS LLEVA</span>',106)+'<div style="font-size:40px;font-weight:600;line-height:1.3;max-width:820px">Estabilidad, tiempo de evolución, frecuencia, ritmo y anticoagulación. Con ficha final para guardar.</div>',cover=True),
page(2,N,T,kicker("PRIMERA PREGUNTA")+big("¿ESTÁ INESTABLE?",140,nowrap=True)+rows(line("Hipotensión con hipoperfusión, isquemia o insuficiencia cardiaca grave atribuibles a la arritmia"),f'<div style="border-top:4px solid {K};padding-top:22px;font-size:46px;font-weight:800;line-height:1.25;color:{R}">Cardioversión eléctrica sincronizada urgente</div>',line("Anticoagulación lo antes posible y, después, al menos 4 semanas"))+note("Busca y trata el desencadenante a la vez: en el anciano, la sepsis es el más frecuente.")),
page(3,N,T,kicker("SI ESTÁ ESTABLE")+big("¿DESDE CUÁNDO?",138,R,True)+rows(row("&lt; 24 h, inicio claro","Cardioversión posible en Urgencias"),row("&gt; 24 h o desconocido","Control de frecuencia"),line("Cardioversión diferida: 3 semanas anticoagulado o ecocardiograma transesofágico",True))+note("El riesgo embólico aumenta ya desde las 12 h. Si dudas de la hora de inicio, trátala como prolongada.")),
page(4,N,T,kicker("CONTROL DE FRECUENCIA")+big("OBJETIVO &lt; 110 LPM",128,R,True)+rows(row("Metoprolol","2,5–5 mg IV en 2 min, hasta 3 dosis"),row("Diltiazem","0,25 mg/kg IV en 2 min"),row("Digoxina","0,25 mg IV y 0,25 mg/6 h (máx. 1 mg)"))+note("Diltiazem no si FEVI &lt; 40 %. No combines diltiazem o verapamilo con betabloqueantes. Con insuficiencia cardiaca: trátala y añade digoxina; amiodarona, como último recurso.")),
page(5,N,T,kicker("CONTROL DEL RITMO · SIN CARDIOPATÍA")+big("CARDIOVERSIÓN FARMACOLÓGICA",96,R)+rows(row("Flecainida","300 mg VO o 1,5–3 mg/kg IV en 20 min"),row("Propafenona","450–600 mg VO o 1,5–2 mg/kg IV en 20 min"),row("Vernakalant","3 mg/kg IV en 10 min"))+f'<div style="border-top:4px solid {K};padding-top:22px;font-size:40px;font-weight:800;line-height:1.3;color:{R}">Con cardiopatía estructural: nada de clase IC. Amiodarona 5–7 mg/kg IV en 30 min</div>'+note("Si el fármaco falla, cardioversión eléctrica; no encadenes un segundo antiarrítmico.")),
page(6,N,T,kicker("ANTES DEL ALTA")+big("¿ANTICOAGULO?",160,nowrap=True)+rows(line("Calcula el riesgo: CHA<sub>2</sub>DS<sub>2</sub>-VASc"),f'<div style="border-top:4px solid {K};padding-top:22px;font-size:44px;font-weight:800;line-height:1.3;color:{R}">≥ 2 en varones o ≥ 3 en mujeres: anticoagulación oral, de preferencia un ACOD</div>',line("Tras cardiovertir: al menos 4 semanas; indefinida si el riesgo es alto"))+note("Equivale a CHA<sub>2</sub>DS<sub>2</sub>-VA ≥ 2 de la ESC 2024, que ya no puntúa el sexo.")),
page(7,N,T,ficha_body("FIBRILACIÓN AURICULAR","Adulto",[("INESTABLE","Cardioversión eléctrica sincronizada urgente + anticoagulación",True),("&lt; 24 H","Inicio claro y estable: cardioversión posible en Urgencias"),("&gt; 24 H / DUDA","Control de frecuencia. Cardioversión tras 3 semanas anticoagulado o ETE"),("FRECUENCIA","&lt; 110 lpm. Metoprolol 2,5–5 mg IV; diltiazem 0,25 mg/kg IV; si IC, digoxina 0,25 mg IV"),("RITMO","Sin cardiopatía: flecainida 300 mg VO o propafenona 450–600 mg VO. Con cardiopatía: amiodarona IV",True),("ANTICOAGULAR","CHA₂DS₂-VASc ≥ 2 (varón) o ≥ 3 (mujer): ACOD")],"Martín A, et al. Consenso SEMES-SEC-SETH 2023. Emergencias 2023;35:359-77",size=92,fs=29),ficha="09"),
]
render(P,sys.argv[1] if len(sys.argv)>1 else "out","fibrilacion-auricular")
